43	/**
44	 * Added at the very end of every premium, after all percentage modifiers, so
45	 * no surcharge or discount is ever computed on top of it.
46	 */
47	const PROCESSING_FEE = 5;
48	
49	/**
50	 * Rates are kept as exact numerator/denominator fractions rather than float
51	 * multipliers (10 / 100, never 1.1) so intermediate amounts stay exact and
52	 * only the final premium is rounded.
53	 */
54	const percent = (amount: number, rate: number): number => (amount * rate) / 100;
55	
56	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
57	const CURSE_SURCHARGE_PERCENT = 50;
58	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
59	const HIGH_ENCHANTMENT_THRESHOLD = 5;
60	
61	/**
62	 * Everything the pricing rules need to know about an item type lives here, so
63	 * that "what is a rune?" has a single answer. Components are the small parts
64	 * (runes, moonstones) that can be bought as a building block; main items
65	 * (swords, amulets, ...) never form a block.
66	 */
67	const ITEM_TYPES: Record<string, { basePremium: number; isComponent: boolean }> =
68	  {
69	    sword: { basePremium: 100, isComponent: false },
70	    amulet: { basePremium: 60, isComponent: false },
71	    staff: { basePremium: 80, isComponent: false },
72	    potion: { basePremium: 40, isComponent: false },
73	    rune: { basePremium: 25, isComponent: true },
74	    moonstone: { basePremium: 25, isComponent: true },
75	  };
76	
77	/** A building block of 3 alike components is offered at this base premium. */
78	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
79	const COMPONENT_BLOCK_SIZE = 3;
80	
81	/** Tallies how many items of each type a policy covers, e.g. [["rune", 3]]. */
82	const countByType = (items: Item[]): [string, number][] => {
83	  const counts = new Map<string, number>();
84	  for (const item of items) {
85	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
86	  }
87	  return [...counts];
88	};
89	
90	/**
91	 * Prices every item of one type together, because exactly 3 alike components
92	 * form a block charged as one. "Alike" means the same type, and the block does
93	 * not repeat: 4 or 7 runes are each priced per item.
94	 */
95	const basePremiumForType = (type: string, count: number): number => {
96	  const { basePremium, isComponent } = ITEM_TYPES[type];
97	  return isComponent && count === COMPONENT_BLOCK_SIZE
98	    ? COMPONENT_BLOCK_BASE_PREMIUM
99	    : count * basePremium;
100	};
101	
102	const sumOfBasePremiums = (items: Item[]): number =>
103	  countByType(items).reduce(
104	    (sum, [type, count]) => sum + basePremiumForType(type, count),
105	    0,
106	  );
107	
108	/**
109	 * Item-specific modifiers: each applies to one item and is charged as a
110	 * percentage of THAT item's own base premium, never of the policy total.
111	 * They stack — an item matching several rules is charged for each.
112	 */
113	const ITEM_MODIFIERS: { appliesTo: (item: Item) => boolean; rate: number }[] = [
114	  { appliesTo: (item) => item.cursed === true, rate: CURSE_SURCHARGE_PERCENT },
115	  {
116	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
117	    rate: HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
118	  },
119	];
120	
121	const surchargeForItem = (item: Item): number =>
122	  ITEM_MODIFIERS.filter(({ appliesTo }) => appliesTo(item)).reduce(
123	    (sum, { rate }) => sum + percent(ITEM_TYPES[item.type].basePremium, rate),
124	    0,
125	  );
126	
127	const sumOfItemSurcharges = (items: Item[]): number =>
128	  items.reduce((sum, item) => sum + surchargeForItem(item), 0);
129	
130	/**
131	 * Policy-wide modifiers: each is charged as a percentage of the POLICY BASE
132	 * premium (the sum of item base premiums, before any item surcharge), so no
133	 * modifier is ever computed on top of another. Discounts carry a negative rate.
134	 */
135	const POLICY_MODIFIERS: {
136	  appliesTo: (customer: Customer) => boolean;
137	  rate: number;
138	}[] = [{ appliesTo: () => true, rate: FIRST_INSURANCE_SURCHARGE_PERCENT }];
139	
140	const sumOfPolicyAdjustments = (
141	  customer: Customer,
142	  policyBasePremium: number,
143	): number =>
144	  POLICY_MODIFIERS.filter(({ appliesTo }) => appliesTo(customer)).reduce(
145	    (sum, { rate }) => sum + percent(policyBasePremium, rate),
146	    0,
147	  );
148	
149	const premiumFor = (customer: Customer, items: Item[]): number => {
150	  const policyBasePremium = sumOfBasePremiums(items);
151	  return Math.ceil(
152	    policyBasePremium +
153	      sumOfItemSurcharges(items) +
154	      sumOfPolicyAdjustments(customer, policyBasePremium) +
155	      PROCESSING_FEE,
156	  );
157	};
158	
159	export const runScenario = (scenario: Scenario): ScenarioResult => {
160	  const quote = scenario.steps[0] as QuoteStep;
161	  return {
162	    results: [{ premium: premiumFor(scenario.customer, quote.items) }],
163	  };
164	};
